INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (19, 10, 'theory', 'Quiz: bridges, veth, VLAN');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 0, 'In the ip -d link output of a bridge you see ageing_time 30000. How long is that?', '["30 seconds", "300 seconds", "30000 seconds", "8.3 hours"]', 1, 'The bridge timers in ip -d link are printed in hundredths of a second, so 30000 is 300 seconds, the default.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 1, 'A frame with an unknown unicast destination arrives on port p2 of a bridge with four ports in the forwarding state. What does the bridge do?', '["Drop the frame", "Send it back out of p2", "Flood it to p1, p3 and p4", "Flood it to all four ports, including p2"]', 2, 'Unknown unicast is flooded to every other forwarding port; the bridge never sends the frame back to the source port. The sender''s address is learned against p2.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 2, 'What is true of the ageing of dynamic FDB entries?', '["The timer restarts on frames received with that address as the source", "The timer restarts on every frame sent to that address", "Entries never age while the port is up", "Entries age after 15 seconds, like the STP states"]', 0, 'The bridge refreshes an entry when it sees the address as a source. Forwarding frames to it does not move the timer, so a silent host is forgotten after ageing_time (300 s by default).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 3, 'A bridge has vlan_filtering 1. An untagged frame arrives on a port with no PVID. What happens?', '["The frame goes into VLAN 1", "The frame is flooded to all VLANs", "The frame passes unchanged, as without filtering", "The frame is dropped"]', 3, 'An untagged frame is assigned to the port''s PVID. With no PVID there is nowhere to put it, and the bridge drops it.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (19, 10, 4, 'What is true of the subinterface eth0.100 created with ip link add link eth0 name eth0.100 type vlan id 100?', '["The VLAN number is taken from the name, so the id is optional", "Its MTU starts equal to the parent''s and cannot be larger", "It accepts frames of any VLAN and strips the tag", "It works only if eth0 is a bridge port"]', 1, 'The id parameter sets the number, the name is only a convention. The subinterface MTU does not exceed the parent''s, and the tag adds 4 bytes to the frame on the wire.');
